 "content": "def transform(grid):
    # Fill the interiors of outlined rectangular frames. The demo indicates
    # the 2x2 interior uses color 2 and larger frame interiors use color 7.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(r.count(v) for r in grid))
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            # Find same-color connected component (4-neighbor).
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            r0=min(y for y,x in cells); r1=max(y for y,x in cells)
            c0=min(x for y,x in cells); c1=max(x for y,x in cells)
            # A rectangular outline is the perimeter of its bounding box.
            if len(cells) == 2*(r1-r0+1)+2*(c1-c0+1)-4 and all(
                (y in (r0,r1) or x in (c0,c1)) for y,x in cells
            ):
                fill = 2 if (r1-r0-1, c1-c0-1) == (2,2) else 7
                for y in range(r0+1,r1):
                    for x in range(c0+1,c1):
                        if out[y][x] == bg:
                            out[y][x] = fill
    return out
"
